public void insertInvoiceDetailsInformation(CustInvoiceJour _custInvoiceJour,
                                            CustInvoiceTrans _custInvoiceTrans,
                                            CustPaymSchedLine _custPaymSchedLine,
                                            CustTrans _prepaymentCustTrans,
                                            TaxTrans _prepaymentTaxTrans)
{
    next insertInvoiceDetailsInformation(_custInvoiceJour, 
                                        _custInvoiceTrans, 
                                        _custPaymSchedLine, 
                                        _prepaymentCustTrans, 
                                        _prepaymentTaxTrans);
}

    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    public void generateInvoiceRelatedInformation(CustInvoiceJour _custInvoiceJour)
    {
        next generateInvoiceRelatedInformation(_custInvoiceJour);

        // Add entries for subs (functionality to be determined).
        this.metAddSubstituteInformation(_custInvoiceJour);
        this.metAddTotalsSection(_custInvoiceJour);
    }

