    /// <summary>
    /// Add totals/sub-totals sections.
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    private void metAddTotalsSection(CustInvoiceJour _custInvoiceJour)
    {
        // Place holder, tbd rebates.
        // Pending requirements.

        Amount totalAmount;

        void add(str _desc, Amount _amount)
        {
            salesInvoiceTmp.METIsTotalLine              = true;
            salesInvoiceTmp.METTotalLineDescription     = _desc;
            salesInvoiceTmp.METTotalLineAmount          = _amount;
            salesInvoiceTmp.insert();

            totalAmount += _amount;
        }

        //add('Sub total',                    _custInvoiceJour.SalesBalance);
        //add('Distribution rebate 0.999%',   _custInvoiceJour.SalesBalance * 0.999);  // ****
        //add('Total',                        totalAmount);
    }

    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_companyInfo">_companyInfo</param>
    protected void populateSalesInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour, 
                                                        CompanyInfo _companyInfo)
    {
        next populateSalesInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);

        custFormLetterParameters = CustFormLetterParameters::find();

        CustTable           custTable           = _custInvoiceJour.custTable_OrderAccount();
        METCustTable        metCustTable        = METCustTable::find(custTable.AccountNum);
        BankAccountTable    eftBankAccount      = BankAccountTable::find(custFormLetterParameters.METInvoiceEFTBankAccountID);
        SalesTable          salesTable          = _custInvoiceJour.salesTable();
        CompanyInfo         companyInfo         = CompanyInfo::find();
        METIndustryKeyTable industryKey         = METIndustryKeyTable::find(METCustTable::find(salesTable.CustAccount).IndustryKey);
        MarkupTrans         markupTransloc;
        MarkupTable         markupTableloc;
        METCustomerLicence  metCustomerLicence;
        METMetcashLicence   metMetcashLicence;
        SysDocuBrandDetails docuBrandDetails;
        SalesLine           salesLineloc;

        Map metChargesComponentMap = new Map(Types::String, Types::Real);
        METSalesLinePriceComponent  metSalesLinePriceComponent,metSalesLinePriceComponentloc;

        salesInvoiceHeaderFooterTmp.CompanyEmail = _companyInfo.email();

        // MPJ-13531
        Image img = CustTable::metGetCustReportLogo(_custInvoiceJour.InvoiceAccount);
        
        if(img)
        {
            salesInvoiceHeaderFooterTmp.companyLogo = img.getData();
        }

        if(!eftBankAccount)
        {
            eftBankAccount = BankAccountTable::find(companyInfo.Bank);
        }

        salesInvoiceHeaderFooterTmp.METInvoiceReportInternetBankingNotes = custFormLetterParameters.METInvoiceReportInternetBankingNotes;
        salesInvoiceHeaderFooterTmp.METEFTAccountDetails    = strFmt('BSB: %1 A/C: %2', eftBankAccount.BankSortCode, eftBankAccount.AccountNum);
        salesInvoiceHeaderFooterTmp.METEFTReferenceText     = custTable.accountnum;//cb272
        salesInvoiceHeaderFooterTmp.METStatementDate        = salesInvoiceHeaderFooterTmp.InvoiceDate;
        salesInvoiceHeaderFooterTmp.METBPayBillerCode       = metCustTable.BPayBillerCode;
        salesInvoiceHeaderFooterTmp.METBPayReference        = metCustTable.BPayReference;
        salesInvoiceHeaderFooterTmp.METDeliveryRoute        = salesTable.METRoute+' / '+ int2Str(salesTable.METRouteStopNum);//Route
        salesInvoiceHeaderFooterTmp.METCustGroup            = custTable.CustGroup;
        salesInvoiceHeaderFooterTmp.METRepCode              = custTable.metGetCustomerAttribute(custTable.AccountNum, METConstants::Agentnumber);
        salesInvoiceHeaderFooterTmp.METBPayMessage          = custFormLetterParameters.METBpayMessageToCustomer;
        salesInvoiceHeaderFooterTmp.METDeliverToName        = salesTable.DeliveryName;
        salesInvoiceHeaderFooterTmp.METDeliverToAddress     = salesTable.deliveryAddress().Address;       
        salesInvoiceHeaderFooterTmp.METPaymTerms            = salesTable.Payment;
        salesInvoiceHeaderFooterTmp.METDueDate              = _custInvoiceJour.DueDate;
        salesInvoiceHeaderFooterTmp.METSalesOrderType       = salesTable.METSalesOrderType;
        salesInvoiceHeaderFooterTmp.METBPayMessage          = custFormLetterParameters.METBpayMessageToCustomer;
        salesInvoiceHeaderFooterTmp.METInvoiceToABN         = custTable.VATNum;
        salesInvoiceHeaderFooterTmp.METSpecialInstruction   = METCustTable::find(custTable.AccountNum).SpecialInstruction;
        salesInvoiceHeaderFooterTmp.METCustOperGroupId      = custTable.METCustOperGroupId;
        
        select firstonly LicenceNumber from metCustomerLicence
            where METCustomerLicence.CustAccount == custTable.AccountNum && metCustomerLicence.Type == METLicenceType::Tobacco;
        
        salesInvoiceHeaderFooterTmp.METCustTobaccoLicense = metCustomerLicence.LicenceNumber;

        select firstonly LicenceNumber from metMetcashLicence
            where metMetcashLicence.InventSiteId == salesTable.InventSiteId && metMetcashLicence.Type == METLicenceType::Tobacco;

        select firstonly LicenceNumber from metCustomerLicence
            where metCustomerLicence.CustAccount == custTable.AccountNum && metCustomerLicence.Type == METLicenceType::Liquor;
            
        salesInvoiceHeaderFooterTmp.METCustLiquorLicense    = metCustomerLicence.LicenceNumber;
        salesInvoiceHeaderFooterTmp.METTobaccolicense       = metMetcashLicence.LicenceNumber;

        select firstonly docuBrandDetails
                where docuBrandDetails.METIndustryKey == industryKey.IndustryKey;

        if (docuBrandDetails)
        {
            salesInvoiceHeaderFooterTmp.CompanyLogo     = SysDocuBrandImages::getImage(docuBrandDetails.Image1Name);
            salesInvoiceHeaderFooterTmp.CompanyName     = industryKey.IndustryChannel;
            salesInvoiceHeaderFooterTmp.CompanyCoRegNum = docuBrandDetails.METTaxRegNumber;
            salesInvoiceHeaderFooterTmp.CompanyPhone    = docuBrandDetails.Phone;
            salesInvoiceHeaderFooterTmp.CompanyEmail    = docuBrandDetails.Email;
            salesInvoiceHeaderFooterTmp.METNotesFooter  = docuBrandDetails.METReportNotes;//CB272
            salesInvoiceHeaderFooterTmp.METSupplierSiteNameAddress = docuBrandDetails.displayAddress();
        }

        while select saleslineloc  
            group by metSalesLinePriceComponent.component,SalesLineloc.inventtransid
                where saleslineloc.SalesId == salesTable.SalesId
            join component from metSalesLinePriceComponent
                where METSalesLinePriceComponent.InventTransId == SalesLineloc.inventtransid
        {
            select sum(value) from metSalesLinePriceComponentloc
                where metSalesLinePriceComponentloc.Component == metSalesLinePriceComponent.Component
                && metSalesLinePriceComponentloc.InventTransId == SalesLineloc.inventtransid;

            if(metChargesComponentMap.exists(metSalesLinePriceComponent.Component))
            {
                metChargesComponentMap.insert(metSalesLinePriceComponent.Component, metChargesComponentMap.lookup(metSalesLinePriceComponent.Component) + metSalesLinePriceComponentloc.Value);
            }
            else
            {
                metChargesComponentMap.insert(metSalesLinePriceComponent.Component, metSalesLinePriceComponentloc.Value);
            }
        }
        
        // DOMS totals
        MapEnumerator metMapEnumeratorStd;
        metMapEnumeratorStd = metChargesComponentMap.getEnumerator();
        while (metMapEnumeratorStd.moveNext())
        {
            salesInvoiceHeaderFooterTmp.METComponentCode        += metMapEnumeratorStd.currentKey() + '\n';
            salesInvoiceHeaderFooterTmp.METComponentVal         += strFmt('%1',metMapEnumeratorStd.currentValue()) + '\n';
            salesInvoiceHeaderFooterTmp.METComponentValueTotal  +=metMapEnumeratorStd.currentValue();
        }

        //Header Delivery and Admin fees
        select sum(Value) from markupTransloc
                where markupTransloc.TransRecId    == _custInvoiceJour.recid && markupTransloc.TransTableId  == _custInvoiceJour.TableId
                join markupTableloc
                    where markupTableloc.MarkupCode == markupTransloc.MarkupCode && markupTableloc.METChargeType == METChargeType::AdminFees;

        salesInvoiceHeaderFooterTmp.METAdminFee = markupTransloc.Value;

        select sum(Value) from markupTransloc
            where markupTransloc.TransRecId == _custInvoiceJour.recid && markupTransloc.TransTableId  == _custInvoiceJour.TableId
                join markupTableloc
            where markupTableloc.MarkupCode == markupTransloc.MarkupCode && markupTableloc.METChargeType == METChargeType::DeliveryFees;

        salesInvoiceHeaderFooterTmp.METDeliveryFee = markupTransloc.Value;

        // only run for food weekly report
        TaxTrans metTaxTransStd;
        custInvoiceJour custInvoiceJourloc;
        select sum(sourceregulateamountcur)
            from metTaxTransStd
                join custInvoiceJourloc
                    where custInvoiceJourloc.InvoiceDate == metTaxTransStd.TransDate
            && custInvoiceJourloc.InvoiceId == _custInvoiceJour.InvoiceId && metTaxTransStd.inventtransid != '';
        
        salesInvoiceHeaderFooterTmp.METGSTTotal = metTaxTransStd.sourceregulateamountcur;
    }

    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_custInvoiceTrans">_custInvoiceTrans</param>
    /// <param name = "_taxSpec">_taxSpec</param>
    /// <param name = "_custPaymSchedLine">_custPaymSchedLine</param>
    /// <param name = "_prepaymentCustTrans">_prepaymentCustTrans</param>
    /// <param name = "_prepaymentTaxTrans">_prepaymentTaxTrans</param>
    protected void populateSalesInvoiceTmp(CustInvoiceJour _custInvoiceJour,
                                            CustInvoiceTrans _custInvoiceTrans,
                                            TaxSpec _taxSpec,
                                            CustPaymSchedLine _custPaymSchedLine,
                                            CustTrans _prepaymentCustTrans,
                                            TaxTrans _prepaymentTaxTrans)
    {
        next populateSalesInvoiceTmp(_custInvoiceJour, 
                                    _custInvoiceTrans, 
                                    _taxSpec, 
                                    _custPaymSchedLine, 
                                    _prepaymentCustTrans, 
                                    _prepaymentTaxTrans);

        if (!salesInvoiceTmp.TaxAmount)
        {
            salesInvoiceTmp.TaxAmount = _custInvoiceTrans.TaxAmount;
        }

        QueryRun tradeLoopTrans = new tradeLoopTrans(_custInvoiceTrans, tableNum(markupTrans)).buildQueryRun();
        
        salesInvoiceTmp.MCRMarkupTxt = SysLabel::labelId2String(literalStr("@SYS308474"),  _custInvoiceJour.LanguageId);

        while (tradeLoopTrans.next())
        {
            MarkupTrans markupTransLocal = tradeLoopTrans.get(tableNum(markupTrans));

            // Filter out ledger to Ledger.
            if (!(markupTransLocal.markuptable().CustType == MarkupType::LedgerAccount &&
                markupTransLocal.markuptable().VendType == MarkupType::LedgerAccount))
            {
                salesInvoiceTmp.MCRMarkupTxt += '\n' + markupTransLocal.MarkupCode + " = " +strFmt('%1',markupTransLocal.CalculatedAmount) ;
            }
        }

        SalesLine salesLine = SalesLine::find(_custInvoiceTrans.InventTransId);

        salesInvoiceTmp.METSalesInvoiceReportLineType   = METSalesInvoiceReportLineType::Line;
        salesInvoiceTmp.METCase = EcoResProductUnitConverter::convertForReleasedProduct(
                                    _custInvoiceTrans.ItemId,
                                    _custInvoiceTrans.InventDimId,
                                    _custInvoiceTrans.Qty, EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_custInvoiceTrans.SalesUnit),
                                    EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(METConstants::unitcase),
                                    NoYes::Yes,
                                    NoYes::No);
        if(_custInvoiceTrans.METCase)
        {
            SalesInvoiceTmp.METCaseCost = salesInvoiceTmp.METWholesaleListPrice+(salesInvoiceTmp.METDeliveryFee+_custInvoiceTrans.lineAmountInclTax())/_custInvoiceTrans.METCase;
        }
        salesInvoiceTmp.METLineNum                      = _custInvoiceTrans.LineNum;       
        salesInvoiceTmp.METUnitPriceExclTax             = _custInvoiceTrans.SalesPrice;
        salesInvoiceTmp.METUnitPriceInclTax             = _custInvoiceTrans.Qty ? (_custInvoiceTrans.lineAmountInclTax() / _custInvoiceTrans.Qty) : 0;
        salesInvoiceTmp.METOrderedQty                   = salesLine.SalesQty;
        //salesInvoiceTmp.METDepartment                   = '[Department]';
        salesInvoiceTmp.METUnitTax                      = _custInvoiceTrans.Qty ? (_custInvoiceTrans.TaxAmount / _custInvoiceTrans.Qty) : 0;
        salesInvoiceTmp.METMarginAmount                 = 1;
        salesInvoiceTmp.METStandardCost                 = 1;
        salesInvoiceTmp.METUnitTax                      = _custInvoiceTrans.Qty ? (_custInvoiceTrans.TaxAmount / _custInvoiceTrans.Qty) : 0;
        salesInvoiceTmp.METProductType                  = METItemType::find(METInventItemOrderSetup::findByItemAndSite(_custInvoiceTrans.ItemId,_custInvoiceTrans.inventSiteId()).ItemType).Description;
        salesInvoiceTmp.METSRP                          = salesInvoiceTmp.LineAmount;
        salesInvoiceTmp.METCAT                          = this.metGetProductAttributeforInvCategory(_custInvoiceTrans.ItemId);//Product category
        salesInvoiceTmp.METINDS                         = salesLine.metSalesLine().Indicators;
        salesInvoiceTmp.METSuppliedQty                  = _custInvoiceTrans.Qty;
        salesInvoiceTmp.METWeight                       = _custInvoiceTrans.METGrossWeight;// cb272 METWHSPhysDimUOMSite::convertWeight(_custInvoiceTrans.ItemId, _custInvoiceTrans.Qty, _custInvoiceTrans.SalesUnit, _custInvoiceTrans.inventDim());

        if(!salesInvoiceTmp.TaxAmount)
        {
            salesInvoiceTmp.METTaxExemptAmount = salesInvoiceTmp.LineAmount;
        }
       
        // For ALM Direct invoice
        METCBCTInvoiceHeaderTable metCBCTInvoiceHeaderTable;
        select sum(VendInvoiceAmtInclGST), sum(VendInvoiceGSTAmount)  from metCBCTInvoiceHeaderTable 
            where metCBCTInvoiceHeaderTable.RefSalesId == _custInvoiceTrans.salesid;

        salesInvoiceTmp.METSupplierInvoiceAmtInclGST = metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST;
        salesInvoiceTmp.METSupplierInvoiceGST = metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount;

        METInventTable  metInventTable = METInventTable::find(_custInvoiceTrans.ItemId);

        salesInvoiceTmp.METAlcoholContent = metInventTable.AlcoholContent;
        salesInvoiceTmp.METCountryCode = metInventTable.CountryCode;

        this.insertMETCTSalesInvoiceTmp(_custInvoiceJour,_custInvoiceTrans);// A condition will have to be added to call this based on report design later "'FoodWeeklyCTInvoice’"
    }

    /// <summary>
    /// MPJ_13531_CustReportLogos
    /// CoC extension.
    /// </summary>
    /// <returns>As std. impl.</returns>
    protected boolean useExistingReportData()
    {
        // MPJ-13531 - Update logo for instances where report data already exists eg reprints.
        SalesInvoiceHeaderFooterTmp headerFooterTmp;
        while select forupdate headerFooterTmp
            where   headerFooterTmp.JournalRecId == this.parmDataContract().parmRecordId()
        {
            Image img = CustTable::metGetCustReportLogo(headerFooterTmp.InvoiceAccount);
            
            if(img)
            {
                headerFooterTmp.companyLogo = img.getData();
                headerFooterTmp.update();
            }
        }

        return next useExistingReportData();
    }

/// <summary>
/// CB272 Sales invoice reports
/// </summary>
/// <returns>METSalesCTInvoiceTmp</returns>
[SRSReportDataSetAttribute(tableStr(METSalesCTInvoiceTmp))]
public METSalesCTInvoiceTmp getMETSalesCTInvoiceTmp()
{
    select metSalesCTInvoiceTmp;
    return metSalesCTInvoiceTmp;
}

    /// <summary>
    /// CB272 - for instering records for FoodLiquor Invoice
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_custInvoiceTrans">_custInvoiceTrans</param>
    public void insertMETCTSalesInvoiceTmp(CustInvoiceJour _custInvoiceJour, CustInvoiceTrans _custInvoiceTrans)
    {
        METCBCTInvoiceHeaderTable   metCBCTInvoiceHeaderTable;
        MarkupTrans  markupTransloc;
        MarkupTable markupTableloc;

        while select metSalesCTInvoiceTmp
            where metSalesCTInvoiceTmp.RefSalesId == _custInvoiceJour.SalesId
        {
            metSalesCTInvoiceTmp.SupplierName           =   metCBCTInvoiceHeaderTable.getVendName(); //suplier name
            metSalesCTInvoiceTmp.VendorAccount          =   metCBCTInvoiceHeaderTable.VendorAccount; //suplier Id
            metSalesCTInvoiceTmp.TaxInvoiceNum          =   metCBCTInvoiceHeaderTable.TaxInvoiceNum;// supplier inv no
            metSalesCTInvoiceTmp.DocumentDate           =   metCBCTInvoiceHeaderTable.DocumentDate; //invoice date
            metSalesCTInvoiceTmp.VendInvoiceAmtInclGST  =   metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST;//incl GST
            metSalesCTInvoiceTmp.VendInvoiceGSTAmount   =   metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount; //GST
            metSalesCTInvoiceTmp.ProdCATDimensionValue  =   this.getDimensionDisplayValue(metCBCTInvoiceHeaderTable.FinancialDimension,METConstants::Department);

            select sum(Value),sum(CalculatedAmount) from markupTransloc
                where markupTransloc.TransRecId    == _custInvoiceJour.recid && markupTransloc.TransTableId  == _custInvoiceJour.TableId
                    join markupTableloc
                where markupTableloc.MarkupCode == markupTransloc.MarkupCode && markupTableloc.METChargeType == METChargeType::ChargeThroughDiscCode1;

            metSalesCTInvoiceTmp.Disc1Amt       = -markupTransloc.CalculatedAmount; //-ve value
            metSalesCTInvoiceTmp.DiscValue1     = markupTransloc.Value; //charges value

            select sum(Value),sum(CalculatedAmount) from markupTransloc
                where markupTransloc.TransRecId    == _custInvoiceJour.recid && markupTransloc.TransTableId  == _custInvoiceJour.TableId
                    join markupTableloc
                where markupTableloc.MarkupCode == markupTransloc.MarkupCode && markupTableloc.METChargeType == METChargeType::ChargeOnChargethrough;

            metSalesCTInvoiceTmp.MarginAmt      = markupTransloc.CalculatedAmount;
            metSalesCTInvoiceTmp.MarginValue    = markupTransloc.Value; //charges value

            select sum(Value),sum(CalculatedAmount) from markupTransloc
                where markupTransloc.TransRecId    == _custInvoiceJour.recid && markupTransloc.TransTableId  == _custInvoiceJour.TableId
                    join markupTableloc
                where markupTableloc.MarkupCode == markupTransloc.MarkupCode && markupTableloc.METChargeType == METChargeType::ChargeThroughDiscCode2;

            metSalesCTInvoiceTmp.Disc2Amt   = -markupTransloc.CalculatedAmount;
            metSalesCTInvoiceTmp.DiscValue2 = markupTransloc.Value;

            TaxTrans metTaxTransStd;
            CustInvoiceJour custInvoiceJourloc;
            CustInvoiceTrans custInvoiceTransloc;
        
            //Actual GST for all lines
            select sum(sourceregulateamountcur)
                from metTaxTransStd
                    join custInvoiceJourloc
                        where custInvoiceJourloc.InvoiceDate == metTaxTransStd.TransDate && custInvoiceJourloc.InvoiceId == _custInvoiceJour.InvoiceId && metTaxTransStd.inventtransid != '';
        
            metSalesCTInvoiceTmp.GSTPayable = metTaxTransStd.sourceregulateamountcur;
            //for GSTFREE.
            select TaxCode, sum(sourcebaseAmountCur) from metTaxTransStd
                group by TaxCode
                    join custInvoiceTransloc
                        where custInvoiceTransloc.InvoiceId == _custInvoiceJour.InvoiceId
                            && metTaxTransStd.InventTransId  == custInvoiceTransloc.InventTransId && metTaxTransStd.TaxCode == METConstants::GSTFree;

            salesInvoiceHeaderFooterTmp.METGSTFree = metTaxTransStd.SourceTaxAmountCur;
            metSalesCTInvoiceTmp.insert();
        }
    }

    /// <summary>
    /// Cb272 Invoicing - VM
    /// Fetch the invoice category value of the product attribute as per requirement
    /// </summary>
    /// <param name = "_itemID">_itemID</param>
    /// <returns>AttributeValueText</returns>
    public AttributeValueText metGetProductAttributeforInvCategory(ItemId _itemID)
    {
        InventTable                 InventTable;
        EcoResProductAttributeValue ecoResProductAttributeValue;
        EcoResAttribute             ecoResAttribute;
        EcoResValue                 ecoResValue;

        select firstonly RecId from InventTable where InventTable.itemid == _itemID
            join RecId,Value from ecoResProductAttributeValue
                where ecoResProductAttributeValue.Product == InventTable.Product
            join Name from ecoResAttribute
                where ecoResProductAttributeValue.Attribute == ecoResAttribute.RecId
                    && ecoResAttribute.Name == METConstants::InvoiceCategory//InvoiceCategory
            join ecoResValue
                where ecoResValue.RecId == ecoResProductAttributeValue.Value;

        return  any2Str(ecoResProductAttributeValue.Value);
    }

/// <summary>
/// Cb272 get default dimension 
/// </summary>
/// <param name = "_defaultDimension">_defaultDimension</param>
/// <param name = "_dimName">_dimName</param>
/// <returns>DimensionValue</returns>
public DimensionValue getDimensionDisplayValue(RecId _defaultDimension, Name _dimName)
{
    DimensionAttributeValueSetStorage dimStorage = DimensionAttributeValueSetStorage::find(_defaultDimension);
    
    return dimStorage.getDisplayValueByDimensionAttribute(DimensionAttribute::findByName(_dimName).RecId);
}
